<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class UpbringingDocuments extends Page{protected static ?string $navigationIcon='heroicon-o-document-text';protected static ?string $navigationLabel='Документы';protected static ?string $navigationGroup='Воспитательная работа';protected static string $view='filament.pages.upbringing-documents';public array $rows=[];public function mount():void{$p=request()->attributes->get('academic_period');if(!$p)return;$this->rows=DB::table('upbringing_document_links as l')->join('official_documents as d','d.id','=','l.official_document_id')->where('d.academic_period_id',$p->id)->select('l.id','l.entity_type','l.entity_id','l.relation','d.number','d.type','d.status','d.created_at')->orderByDesc('d.id')->get()->map(fn($x)=>(array)$x)->all();}}
